const OWNER='plzsayyes3',REPO='my-storage-note',KEY='cockpid.github.token';const $=id=>document.getElementById(id);const token=()=>localStorage.getItem(KEY)||'';function jst(d=new Date()){const s=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);return new Date(`${s.find(x=>x.type==='year').value}-${s.find(x=>x.type==='month').value}-${s.find(x=>x.type==='day').value}T00:00:00+09:00`)}function fmt(d){return d.toISOString().slice(0,10)}function label(n,d){return n===1?'昨日':n===2?'一昨日':`${n}日前`}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function decode(v){const b=atob(v.replace(/\n/g,''));return new TextDecoder().decode(Uint8Array.from(b,c=>c.charCodeAt(0)))}async function load(path){const r=await fetch(`https://api.github.com/repos/${OWNER}/${REPO}/contents/${path}?ref=main`,{headers:{Accept:'application/vnd.github+json',Authorization:`Bearer ${token()}`}});if(r.status===404)return null;if(!r.ok)throw Error(`Storage ${r.status}`);const j=await r.json();return JSON.parse(decode(j.content))}async function days(type,n=7){const base=jst();const out=[];for(let i=1;i<=n;i++){const d=new Date(base);d.setDate(d.getDate()-i);const date=fmt(d);const data=await load(`extracted/${type}/${date}.json`);if(data?.items?.length)out.push({i,date,items:data.items})}return out}function accord(title,rows){return `<h2>${title}</h2>`+(rows.length?rows.map(r=>`<details ${r.i===1?'open':''}><summary>${label(r.i)} <span class="date">${r.date}</span></summary>${r.items.map(x=>`<article class="item"><strong>${esc(x.title||'Untitled')}</strong><p>${esc(x.summary||'')}</p><span class="confidence">${x.confidence==null?'':Math.round(x.confidence*100)+'% confidence'}</span></article>`).join('')}</details>`).join(''):'<p class="meta">No data in the last 7 days.</p>')}async function boot(mode){if(!token()){$('status').textContent='TOKEN REQUIRED';$('dialog')?.showModal?.()}$('save')?.addEventListener('click',()=>{localStorage.setItem(KEY,$('tokenInput').value.trim());location.reload()});try{const[t,i,a]=await Promise.all([days('theme'),days('idea'),days('action')]);$('themes').innerHTML=accord('THEMES',t);$('ideas').innerHTML=accord('IDEAS',i);$('actions').innerHTML=accord('ACTIONS',a);const c=await load('connections/semantic.json');$('connections').innerHTML='<h2>SERENDIPITY / CONNECTIONS</h2>'+((c?.connections||[]).slice(-8).reverse().map(x=>`<article class="item"><strong>${Math.round(x.score*100)}% CONNECTION</strong><p>${esc(x.reason)}</p><span class="meta">${esc(x.from)} → ${esc(x.to)}</span></article>`).join('')||'<p class="meta">No connections</p>');$('status').textContent='LIVE · LAST 7 DAYS'}catch(e){$('status').textContent=e.message}}